from rest_framework.throttling import SimpleRateThrottle
from rest_framework.exceptions import PermissionDenied

class MerchantPayoutRateThrottle(SimpleRateThrottle):
    scope = 'merchant_payout'
    rate = '3/hour'

    def get_cache_key(self, request, view):
        if not request.user or not request.user.is_authenticated:
            return None
        merchant_id = view.kwargs.get('merchant_id')
        if not request.user.merchants.filter(id=merchant_id).exists():
            raise PermissionDenied("You do not manage this merchant.")
        return f"throttle_{self.scope}_{merchant_id}_{request.user.id}"
